{
 "command": "ls tests tests/* | head -50; grep -rn \"statement\\|golden\" --include=*.md --include=*.toml --include=*.cfg --include=Makefile . | head",
 "description": "List test files and look for golden docs"
}

{
 "command": "cat docs/testing.md tests/goldens.py tests/golden/MANIFEST tests/golden/statement_basic.txt; ls tests/golden/inputs; ls scripts tools 2>/dev/null",
 "description": "Read golden testing docs and files"
}

{
 "command": "cat scripts/regen_goldens.py; grep -n \"golden\\|test\" Makefile",
 "description": "Read golden regeneration script and Makefile"
}

{
 "command": "python scripts/regen_goldens.py && git diff tests/ && make test-fast 2>&1 | tail -5",
 "description": "Regenerate goldens, show diff, run tests"
}

{
 "command": "git stash -q && python -m pytest tests/test_currency.py -q 2>&1 | tail -3; git stash pop -q && git status --short",
 "description": "Check currency tests on unmodified tree"
}
